sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    var STEP_SYS_ID = '440cb230fb0d1e1495e5fb3f4eefdc67'; //Submit Record Porducer test step sys_id
    var record_sys_id = steps(STEP_SYS_ID).record_id; // Submitted Record Procucer record sys_id

    var caseGr = new GlideRecord('x_hccc_hoc_ohs_investigation_case');
    caseGr.get(record_sys_id);

	var ohsmUtils = new x_hccc_hoc_ohs.HoCOHSMUtils();
	var true_false;

	var emp_address = ohsmUtils.getEmployerAddress(caseGr);  //Field value "Employer Address"
	var comp_address = ohsmUtils.getComplainantAddress(caseGr); //Field value "Complainant Address"
	var request_time = ohsmUtils.getRequestTime(); //Field value "Employee/Employer request time"
	var cor_actions = ohsmUtils.getCorrectiveActions(caseGr); //Field value "Corrective measures taken"

	var test_time = (new GlideDateTime()).getLocalTime().getByFormat('hh:mm:ss');

	//Check value of field "Employer Address" is correct
	if (emp_address === '131 Queen , Ottawa , 001') {
		gs.info('Field "Employer Address" value is correct');
	} else {
		gs.info('Field "Employer Address" value is incorrect');
		true_false = 0;
	}

	//Check value of field "Complainant Address" is correct
	if (comp_address === 'ATF Street , ATF City , ATF Zip') {
		gs.info('Field "Complainant Address" value is correct');
	} else {
		gs.info('Field "Complainant Address" value is incorrect');
		true_false = 0;
	}

    //Check value of field "Employee/Employer request time" is correct
	if (request_time == test_time) {
		gs.info('Field "Employee/Employer request time" value is correct');
	} else {
		gs.info('Field "Employee/Employer request time" value is incorrect');
		true_false = 0;
	}

	//Check value of field "Corrective measures taken" is correct
	if (cor_actions == '0') {
		gs.info('Field "Corrective measures taken" value is correct');
	} else {
		gs.info('Field "Corrective measures taken" value is incorrect');
		true_false = 0;
	}

	if (true_false == 0) {
        gs.info('Test failed.');
        return false;
    } else {
        gs.info('Test succeeded.');
        return true;
    }

})(outputs, steps, params, stepResult, assertEqual);
